        ui_element_table_slot_01_main_menu_aux->enabled_overlay_vertices[i].y -= 14.0f;
        ui_element_table_slot_01_main_menu_aux->overlay_vertices[i].y -= 14.0f;
    }
}

static __forceinline void translate_layer(
    ui_menu_item_subtemplate_block_t &layer, float x, float y)
{
    for (int i = 0; i < 4; ++i) {
        ui_menu_item_subtemplate_slot_t *slot = (&layer.slot_00) + i;
        slot->x += x;
        slot->y += y;
